    except Exception:
        return False

def build():
    providers=defaultdict(list)

    agents=json.loads((SWARM/"config"/"agents.json").read_text(encoding="utf-8"))
    resources=json.loads((SWARM/"config"/"resource_profiles.json").read_text(encoding="utf-8"))
